/**
 * Capability gaps recorded at build time — shown in the UI instead of being
 * quietly absent (e.g. why no CC0 animal head is grafted onto the mesh body).
 */
export const PACK_BLOCKED: readonly {
  readonly id: string;
  readonly wanted: string;
  readonly verdict: string;
  readonly evidence: string;
  readonly blocker: string;
  readonly shippedInstead: string;
}[] = [
  {
    "id": "quaternius-animal-head-graft",
    "wanted": "Graft a CC0 Quaternius animal head (Fox/Wolf/Husky/Shiba) onto the Universal Base Characters humanoid rig via BoneAttachment3D, per legal-inventory.md's hybrid recommendation.",
    "verdict": "NOT POSSIBLE AT RUNTIME — measured, not assumed.",
    "evidence": "Every quadruped in quaternius-animals-v1 is ONE skinned mesh with no separable head node: wolf.glb contains exactly one mesh ('Wolf', 4 primitives) bound to a single 51-joint skin, and its head geometry is skin-weighted to the 'Head' joint rather than living in its own node. BoneAttachment3D attaches whole NODES, so there is nothing to attach; isolating the head means splitting the mesh by bone weight, which is offline mesh surgery.",
    "blocker": "Blender (or an equivalent weight-aware mesh splitter) is not installed in this environment, and gltf-transform has no split-by-skin-weight operation.",
    "shippedInstead": "The 'body' mount: the CC0 mesh body carries a fully PROCEDURAL beast head (kemono-ubc-body-male/female entries above), plus the three Ultimate Monsters chibi bipeds as complete meshes. The species silhouette rides on the procedural ears/horns/muzzle, which technique.md notes is where species identity actually lives."
  },
  {
    "id": "kaykit-atlas-recolor",
    "wanted": "Per-region recolour on the KayKit Adventurers/Skeletons and 100Avatars lines.",
    "verdict": "NOT SHIPPED — materialPolicy 'preserve'.",
    "evidence": "Each of those characters renders from ONE material backed by a single baked atlas, so binding it to a flat house material would paint the entire character one colour.",
    "blocker": "The fix is either an atlas palette-swap shader (needs the atlas cell layout, an art task) or re-UVing onto the palette strip (a Blender job).",
    "shippedInstead": "The vendor material is preserved and the UI marks these entries 'fixed colours'."
  },
  {
    "id": "oga-base-rigged-stylized-humanoid-yw",
    "wanted": "The CC0 'Base Rigged Stylized Humanoid Character (YW)' as a second anime base.",
    "verdict": "NOT VENDORED (already recorded in index.json notShipped).",
    "evidence": "The only geometry in the OGA archive is a .blend file — no FBX/glTF/DAE export exists.",
    "blocker": "Blender required.",
    "shippedInstead": "The two VRoid CC0 bases plus Godette cover the anime lane."
  }
] as const;
